import React, { useState } from "react";
import { Dialog, DialogActions, DialogContent, DialogTitle, Button, Box, TextField, Stack } from "@mui/material";

const MediaDialog = ({ open, handleClose, handleSend, file, inputRef, value, setValue }) => {
  return (
    <Dialog open={open} onClose={handleClose} sx={{p:3}}>
      <DialogTitle>Preview Media</DialogTitle>
      <DialogContent sx={{pb:1}}>
        <Stack spacing={2}>
          <Box sx={{ width: "100%", display: "flex", justifyContent: "center" , pt:2.5}}>
            {file && file.type.startsWith("image/") && (
              <img src={URL.createObjectURL(file)} alt="Preview" style={{ maxWidth: "100%", maxHeight: "400px" , borderRadius:10}} />
            )}
            {file && file.type.startsWith("video/") && (
              <video controls style={{ maxWidth: "100%", maxHeight: "400px" }}>
                <source src={URL.createObjectURL(file)} type={file.type} />
                Your browser does not support the video tag.
              </video>
            )}
          </Box>
          <TextField
            placeholder="Write a message..."
            inputRef={inputRef}
            fullWidth
            multiline
            variant="outlined"
            value={value}
            onChange={(event) => setValue(event.target.value)}
          />
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose} color="secondary">Cancel</Button>
        <Button variant="contained" onClick={handleSend} color="primary">Send</Button>
      </DialogActions>
    </Dialog>
  );
};

export default MediaDialog;
